-GRANT disputedesk TO CURRENT_USER WITH SET TRUE, INHERIT TRUE;
+GRANT disputedesk TO CURRENT_USER WITH SET TRUE, INHERIT FALSE;
 CREATE DATABASE disputedesk OWNER disputedesk;
@@ -23,3 +23,3 @@
